1605	/**
1606	 * Parses a raw string as a positive integer insight ID.
1607	 *
1608	 * Rejects:
1609	 * - Non-numeric strings (NaN after Number())
1610	 * - Floating-point strings (any string containing '.', e.g. "1.5", "2.0")
1611	 * - Zero or negative integers
1612	 *
1613	 * The decimal-point check is performed on the raw string before numeric
1614	 * coercion so that "2.0" (which coerces to an integer) is still rejected.
1615	 *
1616	 * @throws ApiError VALIDATION_ERROR for any rejected value.
1617	 */
1618	function parseKnowledgeId(raw: string): number {
1619	  // Reject strings containing a decimal point before numeric coercion —
1620	  // this catches "1.5" and also "2.0", both of which the caller must treat
1621	  // as non-integer IDs even though Number("2.0") === 2.
1622	  if (raw.includes('.')) {
1623	    throw new ApiError('VALIDATION_ERROR', 'Invalid insight id.');
1624	  }
1625	  const n = Number(raw);
1626	  if (!Number.isInteger(n) || n <= 0) {
1627	    throw new ApiError('VALIDATION_ERROR', 'Invalid insight id.');
1628	  }
1629	  return n;
1630	}
